 sealed record Option(string Id,string Label){public override string ToString()=>Label;}
 static void SelectOption(ComboBox box,string id){for(int i=0;i<box.Items.Count;i++)if(box.Items[i] is Option o&&o.Id==id)box.SelectedIndex=i;}
 async Task RefreshModels(){models=(await manager.Request("list")).Deserialize<List<Model>>()??new();speakerModels=(await manager.Request("speaker-models")).Deserialize<List<SpeakerModel>>()??new();syncing=true;try{void Fill(ComboBox box,IEnumerable<Model> list,string id){box.Items.Clear();box.Items.AddRange(list.Cast<object>().ToArray());for(int i=0;i<box.Items.Count;i++)if(box.Items[i] is Model entry&&entry.Id==id)box.SelectedIndex=i;}Fill(readingModel,new[]{new Model{Id="system",Name="Windows offline voices",Installed=true,Task="tts"}}.Concat(models.Where(m=>m.Task=="tts")),prefs.ReadingModel);Fill(dictationModel,models.Where(m=>m.Task=="stt"&&m.VariantOf==null),prefs.DictationModel);Fill(transcriptionModel,models.Where(m=>m.Task=="stt"&&m.VariantOf==null),prefs.TranscriptionModel);speakerChoice.Items.Clear();speakerChoice.Items.AddRange(speakerModels.Cast<object>().ToArray());for(int i=0;i<speakerChoice.Items.Count;i++)if(speakerChoice.Items[i] is SpeakerModel entry&&entry.Id==prefs.SpeakerModel)speakerChoice.SelectedIndex=i;}finally{syncing=false;}RefreshVoices();modelList.Controls.Clear();modelList.Controls.Add(new Label{Text="Downloads happen only when you choose Install. All reading, dictation, and transcription run locally afterward.",Width=900,Height=45});foreach(var m in models.Where(m=>m.VariantOf==null)){var panel=new FlowLayoutPanel{Width=900,AutoSize=true,Padding=new Padding(0,8,0,8)};panel.Controls.Add(new Label{Text=$"{m.Name}\n{m.SizeMB:0} MB · {(m.Installed?"installed":"not installed")}",Width=320,Height=50});var install=AsyncButton(m.Installed?"Remove":"Install",async()=>{await ModelOperation(m.Id,m.Installed?"remove":"install");});panel.Controls.Add(install);var companion=models.FirstOrDefault(g=>g.VariantOf==m.Id);if(companion!=null)panel.Controls.Add(AsyncButton(companion.Installed?"Remove GPU files":$"Get GPU files · {companion.SizeMB:0} MB",async()=>await ModelOperation(companion.Id,companion.Installed?"remove":"install")));modelList.Controls.Add(panel);}ApplyTheme(modelList);}
 async Task ModelOperation(string id,string command){if(working||recorder.Active||recordingFinishing||readingCancel!=null)throw new InvalidOperationException("Stop audio work before changing installed models.");modelList.Enabled=false;Toast(command=="install"?"Downloading and verifying model files…":"Removing model…",600);try{await manager.Request(command,new{model=id});await RefreshModels();Toast(command=="install"?"Model downloaded and verified.":"Model removed.");}finally{modelList.Enabled=true;}}
 void RefreshVoices(){syncing=true;try{voices.Items.Clear();if(prefs.ReadingModel=="system")voices.Items.AddRange(systemVoice.GetInstalledVoices().Where(v=>v.Enabled).Select(v=>new Voice{Id=v.VoiceInfo.Name,Name=v.VoiceInfo.Name}).Cast<object>().ToArray());else voices.Items.AddRange((models.FirstOrDefault(m=>m.Id==prefs.ReadingModel)?.Voices??Array.Empty<Voice>()).Cast<object>().ToArray());var selected=prefs.ReadingModel=="system"?prefs.ReadingVoice:prefs.Voices.GetValueOrDefault(prefs.ReadingModel);for(int i=0;i<voices.Items.Count;i++)if(voices.Items[i] is Voice entry&&entry.Id==selected)voices.SelectedIndex=i;if(voices.SelectedIndex<0&&voices.Items.Count>0)voices.SelectedIndex=0;if(voices.SelectedItem is Voice chosen){if(prefs.ReadingModel=="system")prefs.ReadingVoice=chosen.Id;else prefs.Voices[prefs.ReadingModel]=chosen.Id;Save();}}finally{syncing=false;}}
 void CaptureShortcut(Button button,bool reading){
  if(button.Tag is Action oldCapture)oldCapture();
  Native.UnregisterHotKey(Handle,1);Native.UnregisterHotKey(Handle,2);
  button.Text="Press Ctrl / Alt / Shift + a key…";button.Focus();
  KeyEventHandler? capture=null;EventHandler? lost=null;bool finished=false;
  void Finish(){if(finished)return;finished=true;button.KeyDown-=capture;button.LostFocus-=lost;button.Tag=null;button.Text=Native.ShortcutName(reading?prefs.ReadModifiers:prefs.DictateModifiers,reading?prefs.ReadKey:prefs.DictateKey);RegisterShortcuts();}
  capture=(_,e)=>{
   e.SuppressKeyPress=true;if(e.KeyCode==Keys.Escape){Finish();return;}
   if(e.KeyCode is Keys.ControlKey or Keys.ShiftKey or Keys.Menu or Keys.LWin or Keys.RWin)return;
   uint mods=(e.Control?2u:0)|(e.Alt?1u:0)|(e.Shift?4u:0),key=(uint)e.KeyCode;
   if(mods==0){Toast("Include Ctrl, Alt, or Shift with a letter or number.");return;}
   if(mods==(reading?prefs.DictateModifiers:prefs.ReadModifiers)&&key==(reading?prefs.DictateKey:prefs.ReadKey)){Toast("Read and dictation need different shortcuts.");return;}
   int id=reading?1:2;
   if(!Native.RegisterHotKey(Handle,id,mods|0x4000,key)){Toast("That shortcut is in use or reserved by Windows. Choose another.");return;}
   Native.UnregisterHotKey(Handle,id);
   if(reading){prefs.ReadModifiers=mods;prefs.ReadKey=key;}else{prefs.DictateModifiers=mods;prefs.DictateKey=key;}
   Save();Finish();
  };
  lost=(_,_)=>Finish();button.Tag=(Action)Finish;button.KeyDown+=capture;button.LostFocus+=lost;
 }

 bool RegisterShortcuts(){Native.UnregisterHotKey(Handle,1);Native.UnregisterHotKey(Handle,2);bool read=Native.RegisterHotKey(Handle,1,prefs.ReadModifiers|0x4000,prefs.ReadKey),dictate=Native.RegisterHotKey(Handle,2,prefs.DictateModifiers|0x4000,prefs.DictateKey);if(!read||!dictate)Toast("Some shortcuts are already used by Windows or another app. Change them in Settings.",10);return read&&dictate;}
 protected override void WndProc(ref Message m){if(m.Msg==0x0312){if(m.WParam.ToInt32()==1)_ =Safe(ReadSelection);else if(m.WParam.ToInt32()==2)_ =Safe(()=>ToggleDictation());}base.WndProc(ref m);}
 async Task ReadSelection(){if(Native.GetForegroundWindow()==Handle){await StartReading();return;}await Native.WaitForModifiers();uint before=Native.GetClipboardSequenceNumber();Native.Shortcut(0x43);for(int i=0;i<20&&Native.GetClipboardSequenceNumber()==before;i++)await Task.Delay(50);if(Native.GetClipboardSequenceNumber()==before||!Clipboard.ContainsText())throw new InvalidOperationException("No selected text was copied. Select text in the other app, or copy and paste it into Read.");editor.Text=Clipboard.GetText();ShowSentences();tabs.SelectedIndex=0;await StartReading();}
 void Save(){try{prefs.Save();}catch(Exception e){Toast("Preferences were not saved: "+e.Message,12);}}
 void Copy(string text){if(string.IsNullOrEmpty(text))return;Clipboard.SetText(text);}
 async Task Safe(Func<Task> action){try{await action();}catch(OperationCanceledException){Toast("Canceled. Completed transcript passages are preserved.");}catch(Exception e){overlay.Hide();Toast(e.Message,12);}}
 void Toast(string text,int seconds=7){if(IsDisposed)return;notice.Text=text;noticeUntil=DateTime.UtcNow.AddSeconds(seconds);noticeProgress.Value=100;}
 void Tick(){if(hoverNotice)noticeUntil=DateTime.UtcNow.AddSeconds(4);double remaining=(noticeUntil-DateTime.UtcNow).TotalSeconds;if(remaining<=0){notice.Text="";noticeProgress.Value=0;}else noticeProgress.Value=Math.Clamp((int)(remaining/7*100),0,100);if(filePlayer.Playing){int index=transcript.Captions.FindIndex(c=>c.Start<=filePlayer.Position&&c.End>filePlayer.Position);if(index>=0&&index<captions.Rows.Count){captions.ClearSelection();captions.Rows[index].Selected=true;}}if(recorder.Active&&recorderTime.Elapsed.TotalSeconds>299)_ =Safe(()=>ToggleDictation());}
 readonly Stopwatch recorderTime=new();
 static void ApplyTheme(Control root){foreach(Control control in root.Controls){control.ForeColor=Color.FromArgb(224,230,238);control.BackColor=control is TextBoxBase or ListBox or ComboBox?Color.FromArgb(30,36,45):Color.FromArgb(24,28,35);if(control is Button button){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderColor=Color.FromArgb(75,90,109);button.Padding=new Padding(5);button.MinimumSize=new Size(80,32);}if(control is DataGridView grid){grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(38,45,57);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;grid.DefaultCellStyle.BackColor=Color.FromArgb(25,30,38);grid.DefaultCellStyle.ForeColor=Color.White;grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(49,78,115);grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}ApplyTheme(control);}}
}
